// Pseudo ingestion function demonstrating key concepts
async function processTelemetry(events) {
  // Deduplicate using TenantId+MessageId composite key
  const uniqueEvents = await deduplicate(events, 
    (e) => `${e.tenantId}:${e.messageId}`);

  // Normalize schema across tenants
  const normalized = uniqueEvents.map(normalizeSchema);

  // Enrich with tenant-specific metadata
  const enriched = await enrichWithTenantData(normalized);

  // Write to ADX with idempotent operations
  await writeToADX(enriched, { 
    table: getTenantTable(enriched[0].tenantId),
    idempotencyKey: 'messageId'
  });
}
```

## Why This Is Asked
Tests ability to design scalable, compliant flag systems across regions with strict latency.

## Key Concepts
- Azure API Management, Functions, Cosmos DB per-tenant partitioning
- Redis caching and cache invalidation
- Canary rollouts, versioning, Event Grid
- Observability and failure handling

## Code Example
```javascript
// Flag evaluation sketch
async function getFlag(tenantId, flagName) {
  const cacheKey = `${tenantId}:${flagName}`;
  let value = await redis.get(cacheKey);
  if (value != null) return JSON.parse(value);
  const flagDoc = await cosmos.Flags.findOne({ tenantId, flagName });
  value = flagDoc?.value ?? false;
  await redis.set(cacheKey, JSON.stringify(value), { ttl: 60 });
  return value;
}
```

